import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 출장·외근 신청 결재 양식 이름. 설정으로 빼기 전까지 이 상수를 쓴다.
const ATTENDANCE_FORM_NAME = '출장·외근 신청';

@Controller('api/v1')
export class FnSfr01810Controller {
  @Post('/attendance-requests/:attendanceRequestId/submit')
  @HttpCode(200)
  async submitAttendanceRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const requestId = req.params['attendanceRequestId'];
    if (!/^[0-9]{1,18}$/.test(requestId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '근태 신청 번호가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT attendance_request_id AS "attendanceRequestId", attendance_type AS "attendanceType", '
          + 'to_char(start_date, 'YYYY-MM-DD') AS "startDate", to_char(end_date, 'YYYY-MM-DD') AS "endDate", '
          + 'reason AS "reason", approval_status AS "approvalStatus", approval_document_id AS "approvalDocumentId" '
          + 'FROM attendance_request WHERE attendance_request_id = CAST(:id AS bigint)',
        { id: requestId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ATTENDANCE_REQUEST_NOT_FOUND', '근태 신청을 찾을 수 없습니다.');
      }
      const row = rows[0];
      if (row.approvalStatus !== '신청' || row.approvalDocumentId !== null) {
        throw new ApiError(409, 'ATTENDANCE_REQUEST_ALREADY_SUBMITTED', '이미 상신했거나 승인된 신청입니다.');
      }
      const forms = await db.query(
        'SELECT approval_form_id AS "formId" FROM approval_form '
          + 'WHERE form_name = :formName AND use_status = '사용' ORDER BY approval_form_id LIMIT 1',
        { formName: ATTENDANCE_FORM_NAME },
      );
      if (forms.length === 0) {
        throw new ApiError(502, 'APPROVAL_LINK_FAILED', '전자결재 양식을 찾지 못해 상신하지 못했습니다.');
      }
      const title = row.attendanceType + ' 신청 (' + row.startDate + ' ~ ' + row.endDate + ')';
      const docs = await db.query(
        'INSERT INTO approval_document (document_no, approval_form_id, drafter_id, title, body, approval_status, submitted_at, created_at, updated_at) '
          + 'VALUES ('ATT-' || CAST(:id AS text), CAST(:formId AS bigint), CAST(:userId AS bigint), :title, :body, '결재대기', now(), now(), now()) '
          + 'RETURNING approval_document_id AS "approvalDocumentId"',
        { id: requestId, formId: forms[0].formId, userId: user.id, title: title, body: row.reason },
      );
      const changed = await db.execute(
        'UPDATE attendance_request SET approval_document_id = CAST(:docId AS bigint), updated_at = now() '
          + 'WHERE attendance_request_id = CAST(:id AS bigint) AND approval_status = '신청' AND approval_document_id IS NULL',
        { docId: docs[0].approvalDocumentId, id: requestId },
      );
      if (changed === 0) {
        throw new ApiError(409, 'ATTENDANCE_REQUEST_ALREADY_SUBMITTED', '이미 상신했거나 승인된 신청입니다.');
      }
      return { approvalDocumentId: docs[0].approvalDocumentId };
    });
  }
}

