import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  DateInput,
  Select,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const TYPES: [string, string][] = [
  ['출장', '출장'],
  ['외근', '외근'],
];

const STATUSES: [string, string][] = [
  ['신청', '신청'],
  ['마감', '마감'],
  ['마감 취소', '마감 취소'],
  ['승인', '승인'],
  ['승인 취소', '승인 취소'],
  ['반려', '반려'],
];

export default function FnSfr01810Page({ role, notify }: PageProps) {
  const [typeInput, setTypeInput] = useState('');
  const [statusInput, setStatusInput] = useState('');
  const [query, setQuery] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);
  const [submitting, setSubmitting] = useState<Row | null>(null);
  const [form, setForm] = useState<Row>({ attendanceType: '출장', startDate: '', endDate: '', reason: '' });

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/attendance-requests', role, undefined, { ...query, page, size: 20 }),
    [query, page],
  );

  const search = () => {
    setPage(0);
    setQuery({ attendanceType: typeInput, approvalStatus: statusInput });
  };

  const reset = () => {
    setTypeInput('');
    setStatusInput('');
    setPage(0);
    setQuery({});
  };

  const create = async () => {
    if (!form.attendanceType || !form.startDate || !form.endDate) {
      throw new Error('근태 유형, 시작일, 종료일을 모두 입력해 주세요.');
    }
    await call('POST', '/attendance-requests', role, {
      attendanceType: form.attendanceType,
      startDate: form.startDate,
      endDate: form.endDate,
      reason: form.reason,
    });
    notify('출장·외근 신청을 등록했습니다.');
    setCreating(false);
    setForm({ attendanceType: '출장', startDate: '', endDate: '', reason: '' });
    reload();
  };

  const submit = async () => {
    if (!submitting) return;
    await call('POST', '/attendance-requests/' + String(submitting.attendanceRequestId) + '/submit', role, {});
    notify('결재 상신했습니다.');
    setSubmitting(null);
    setSelected(null);
    reload();
  };

  const set = (key: string, value: unknown) => setForm({ ...form, [key]: value });

  if (selected) {
    return (
      <div className="doc">
        <button className="ghost" onClick={() => setSelected(null)}>목록으로 돌아가기</button>
        <section className="box">
          <h2>출장·외근 신청 내용</h2>
          <Pairs
            items={[
              ['근태 유형', String(selected.attendanceType)],
              ['시작일', <DateText value={selected.startDate} />],
              ['종료일', <DateText value={selected.endDate} />],
              ['사유', String(selected.reason ?? '')],
              ['변경 근무시간', String(selected.changedWorkTime ?? '')],
              ['승인 처리 상태', <Badge value={selected.approvalStatus} />],
            ]}
          />
        </section>
        {selected.approvalStatus === '신청' && (
          <section className="box">
            <h2>결재 상신</h2>
            <button onClick={() => setSubmitting(selected)}>결재 상신</button>
          </section>
        )}
        {submitting && (
          <Drawer title="결재 상신" onClose={() => setSubmitting(null)}>
            <Form
              onSubmit={submit}
              submit="상신"
              note="상신하면 전자결재 문서가 만들어지고 결재가 시작됩니다."
            >
              <Pairs
                items={[
                  ['근태 유형', String(submitting.attendanceType)],
                  ['기간', <span><DateText value={submitting.startDate} /> ~ <DateText value={submitting.endDate} /></span>],
                ]}
              />
            </Form>
          </Drawer>
        )}
      </div>
    );
  }

  return (
    <div>
      <Filters onSearch={search} onReset={reset}>
        <Field label="근태 유형">
          <Select value={typeInput} onChange={setTypeInput} options={TYPES} placeholder="전체" />
        </Field>
        <Field label="승인 처리 상태">
          <Select value={statusInput} onChange={setStatusInput} options={STATUSES} placeholder="전체" />
        </Field>
      </Filters>
      <Band total={data?.total}>
        <button onClick={() => setCreating(true)}>출장·외근 신청</button>
      </Band>
      {error && <ErrorText text={error} />}
      <DataTable
        columns={[
          { key: 'attendanceType', label: '근태 유형' },
          { key: 'startDate', label: '시작일', render: (r) => <DateText value={r.startDate} /> },
          { key: 'endDate', label: '종료일', render: (r) => <DateText value={r.endDate} /> },
          { key: 'approvalStatus', label: '승인 처리 상태', render: (r) => <Badge value={r.approvalStatus} /> },
          {
            key: 'action',
            label: '처리',
            render: (r) =>
              r.approvalStatus === '신청' ? (
                <button
                  className="ghost"
                  onClick={(e) => {
                    e.stopPropagation();
                    setSelected(r);
                    setSubmitting(r);
                  }}
                >
                  결재 상신
                </button>
              ) : null,
          },
        ]}
        rows={data?.items ?? []}
        onRowClick={(r) => setSelected(r)}
        empty={loading ? '불러오는 중입니다.' : '아직 등록한 출장·외근 신청이 없습니다. 신청 버튼을 눌러 등록해 주세요.'}
      />
      <Pager page={page} size={data?.size ?? 20} total={data?.total ?? 0} onPage={setPage} />
      {creating && (
        <Drawer title="출장·외근 신청" onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit="등록">
            <Field label="근태 유형" required>
              <Select value={form.attendanceType} onChange={(v) => set('attendanceType', v)} options={TYPES} />
            </Field>
            <Field label="시작일" required>
              <DateInput value={form.startDate} onChange={(v) => set('startDate', v)} />
            </Field>
            <Field label="종료일" required>
              <DateInput value={form.endDate} onChange={(v) => set('endDate', v)} />
            </Field>
            <Field label="사유" wide>
              <TextInput value={form.reason} onChange={(v) => set('reason', v)} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
